<script>

var FORM_TEMPLATE_STORAGE_KEY = 'CHAR_FORM_TEMPLATES_V1';
var FORM_LAST_SNAPSHOT_KEY = 'CHAR_FORM_LAST_SNAPSHOT_V1';
var 开场世界线已初始化 = false;
var 开场待发送文本 = '';
var 开场初始化结果 = null;
var 开场主按钮处理中 = false;
var 当前原著角色选择 = '';

var timelineData = {
  "6岁": {
    world: {
      时间: {
        tick: 1036800001
      }
    }
  },
  "9岁": {
    world: {
      时间: {
        tick: 1036960035
      }
    }
  },
  "13岁": {
    world: {
      时间: {
        tick: 1037149235
      }
    }
  }
};

function 获取开场宿主窗口() {
    return window.parent || window.top || window;
}

function 克隆JSON值(值, 兜底) {
    if (值 === undefined || 值 === null) return 兜底;
    try {
        return JSON.parse(JSON.stringify(值));
    } catch (错误) {
        return 兜底;
    }
}

function 读取开场内置角色库() {
    var 窗口列表 = [window, window.parent, window.top, 获取开场宿主窗口()];
    for (var 序号 = 0; 序号 < 窗口列表.length; 序号++) {
        try {
            var 角色库 = 窗口列表[序号] && 窗口列表[序号].__LWCS_内置角色库__;
            if (角色库 && 角色库.角色 && typeof 角色库.角色 === 'object') return 角色库;
        } catch (_) {}
    }
    return null;
}

function 读取开场tick(时间线节点) {
    return (timelineData[时间线节点] && timelineData[时间线节点].world && timelineData[时间线节点].world.时间)
        ? Number(timelineData[时间线节点].world.时间.tick || 0)
        : 0;
}

function 读取原著角色节点年龄(节点) {
    var 匹配 = String(节点 || '').match(/(\d+(?:\.\d+)?)\s*岁/);
    var 年龄 = 匹配 ? Number(匹配[1]) : NaN;
    return Number.isFinite(年龄) ? 年龄 : null;
}

function 读取原著角色快照年龄(快照) {
    var 节点年龄 = 读取原著角色节点年龄(快照 && 快照.节点);
    if (节点年龄 !== null) return 节点年龄;
    var 年龄 = Number(快照 && (快照.年龄 !== undefined ? 快照.年龄 : 快照.角色 && 快照.角色.属性 && 快照.角色.属性.年龄));
    return Number.isFinite(年龄) ? 年龄 : 0;
}

function 取原著角色快照(角色记录, 时间线节点) {
    var 快照列表 = Array.isArray(角色记录 && 角色记录.快照) ? 角色记录.快照 : [];
    if (!快照列表.length) return null;
    var 指定快照 = 快照列表.find(function(快照) {
        return String(快照 && 快照.节点 || '').trim() === 时间线节点;
    });
    if (指定快照) return 指定快照;
    var 当前tick = 读取开场tick(时间线节点);
    var 有tick快照 = 快照列表.filter(function(快照) {
        return Number.isFinite(Number(快照 && 快照.tick));
    });
    if (!有tick快照.length) return 快照列表[0];
    var 之前快照 = 有tick快照
        .filter(function(快照) { return Number(快照.tick) <= 当前tick; })
        .sort(function(a, b) { return Number(b.tick) - Number(a.tick); })[0];
    if (之前快照) return 之前快照;
    return 有tick快照.sort(function(a, b) { return Number(a.tick) - Number(b.tick); })[0];
}

function 计算原著角色投影年龄(角色库, 快照, 当前tick) {
    var 快照年龄 = 读取原著角色快照年龄(快照);
    if (快照 && 快照.固定年龄投影 === true) return 快照年龄;
    var 快照tick = Number(快照 && 快照.tick);
    if (!Number.isFinite(快照tick)) return 快照年龄;
    var 每年tick = Math.max(1, Number(角色库 && 角色库.每年tick || 51840));
    return Math.max(0, 快照年龄 + (Number(当前tick || 0) - 快照tick) / 每年tick);
}

function 角色库天赋转表单选项(天赋梯队) {
    var 文本 = String(天赋梯队 || '').trim();
    if (文本 === '绝世妖孽') return 'EX';
    if (文本 === '顶级天才') return 'S';
    if (文本 === '天才') return 'A';
    if (文本 === '优秀') return 'B';
    if (文本 === '劣等' || 文本 === '天赋极差') return 'D';
    return 'C';
}

function 格式化开场表单文本(值) {
    if (值 === undefined || 值 === null) return '';
    if (typeof 值 === 'string') return 值;
    if (Array.isArray(值)) return 值.map(格式化开场表单文本).filter(Boolean).join('、');
    if (typeof 值 === 'object') {
        return Object.entries(值)
            .map(function(条目) {
                var 子值 = 格式化开场表单文本(条目[1]);
                return 子值 ? 条目[0] + '：' + 子值 : '';
            })
            .filter(Boolean)
            .join('；');
    }
    return String(值);
}

function 读取原著角色武魂表单(角色数据) {
    var 武魂列表 = ['第1武魂', '第2武魂']
        .map(function(槽位) { return 角色数据 && 角色数据[槽位] && typeof 角色数据[槽位] === 'object' ? 角色数据[槽位] : null; })
        .filter(function(武魂) {
            var 名称 = String(武魂 && 武魂.表象名称 || '').trim();
            return 名称 && 名称 !== '无' && 名称 !== '未展露';
        });
    return {
        名称: 武魂列表.map(function(武魂) { return String(武魂.表象名称 || '').trim(); }).join(' '),
        系别: 武魂列表.map(function(武魂) { return String(武魂.系别 || '强攻系').trim() || '强攻系'; }),
        描述: 武魂列表.map(function(武魂) { return String(武魂.描述 || '').trim(); }),
    };
}

function 读取原著角色副职业表单(角色数据) {
    var 副职业表 = 角色数据 && 角色数据.副职业 && typeof 角色数据.副职业 === 'object' ? 角色数据.副职业 : {};
    var 条目 = Object.entries(副职业表).find(function(项) { return 项[1] && typeof 项[1] === 'object'; });
    if (!条目) return { 类型: '无', 等级: '1' };
    var 副职业名 = 条目[0];
    var 数据 = 条目[1] || {};
    var 等级 = Math.max(1, Math.min(9, Math.floor(Number(数据.等级 || 0) || 0)));
    if (!等级) {
        var 称号 = String(数据.称号 || '');
        var 匹配 = 称号.match(/([一二三四五六七八九])级|(\d+)级/);
        var 中文等级 = { 一: 1, 二: 2, 三: 3, 四: 4, 五: 5, 六: 6, 七: 7, 八: 8, 九: 9 };
        等级 = 匹配 ? (中文等级[匹配[1]] || Number(匹配[2]) || 1) : 1;
    }
    var 表单类型 = { 设计师: '机甲设计师', 制造师: '机甲制造师', 修理师: '机甲修理师' }[副职业名] || 副职业名;
    return { 类型: 表单类型, 等级: String(Math.max(1, Math.min(9, 等级))) };
}

function 设置表单值(元素编号, 值, 触发事件) {
    var 元素 = document.getElementById(元素编号);
    if (!元素 || 值 === undefined || 值 === null) return;
    元素.value = 值;
    if (触发事件) {
        元素.dispatchEvent(new Event('input', { bubbles: true }));
        元素.dispatchEvent(new Event('change', { bubbles: true }));
    }
}

function 构建原著角色开场投影(角色名, 时间线节点) {
    var 角色库 = 读取开场内置角色库();
    var 角色记录 = 角色库 && 角色库.角色 ? 角色库.角色[角色名] : null;
    if (!角色库 || !角色记录) return null;
    var 当前tick = 读取开场tick(时间线节点);
    var 快照 = 取原著角色快照(角色记录, 时间线节点);
    if (!快照 || !快照.角色 || typeof 快照.角色 !== 'object') return null;
    var 角色数据 = 克隆JSON值(快照.角色, {});
    if (!角色数据.属性 || typeof 角色数据.属性 !== 'object') 角色数据.属性 = {};
    var 投影年龄 = 计算原著角色投影年龄(角色库, 快照, 当前tick);
    角色数据.属性.年龄 = Number(投影年龄.toFixed(1));
    return {
        角色名: 角色名,
        角色记录: 角色记录,
        快照: 快照,
        角色数据: 角色数据,
        当前tick: 当前tick,
        需要重算等级: Number(快照.tick || 0) > 当前tick,
    };
}

function 读取开局模式() {
    var 元素 = document.getElementById('startup-mode');
    return 元素 && 元素.value === '原著角色' ? '原著角色' : '原创角色';
}

function 刷新原著角色选择() {
    var 选择框 = document.getElementById('original-character-select');
    if (!选择框) return;
    var 旧值 = 选择框.value || 当前原著角色选择 || '';
    var 角色库 = 读取开场内置角色库();
    var 时间线节点 = (document.getElementById('timeline-select') || {}).value || '13岁';
    选择框.innerHTML = '';
    var 占位 = document.createElement('option');
    占位.value = '';
    占位.textContent = 角色库 ? '选择原著角色' : '角色库未加载';
    选择框.appendChild(占位);
    if (!角色库) return;
    var 条目列表 = Object.entries(角色库.角色 || {})
        .map(function(条目) {
            var 角色名 = String(条目[0] || '').trim();
            var 角色记录 = 条目[1] || {};
            var 常驻 = Array.isArray(角色记录.开场常驻节点) && 角色记录.开场常驻节点.indexOf(时间线节点) >= 0;
            var 首次登场 = Number(角色记录.首次登场tick);
            return { 角色名: 角色名, 角色记录: 角色记录, 常驻: 常驻, 首次登场: Number.isFinite(首次登场) ? 首次登场 : 999999999 };
        })
        .filter(function(条目) { return 条目.角色名; })
        .sort(function(a, b) {
            if (a.常驻 !== b.常驻) return a.常驻 ? -1 : 1;
            return a.首次登场 - b.首次登场 || a.角色名.localeCompare(b.角色名, 'zh-Hans-CN');
        });
    var 当前分组 = document.createElement('optgroup');
    当前分组.label = 时间线节点 + '常驻';
    var 其他分组 = document.createElement('optgroup');
    其他分组.label = '其他原著角色';
    条目列表.forEach(function(条目) {
        var 选项 = document.createElement('option');
        选项.value = 条目.角色名;
        选项.textContent = 条目.角色名;
        (条目.常驻 ? 当前分组 : 其他分组).appendChild(选项);
    });
    if (当前分组.children.length) 选择框.appendChild(当前分组);
    if (其他分组.children.length) 选择框.appendChild(其他分组);
    if (旧值 && 角色库.角色[旧值]) {
        选择框.value = 旧值;
    } else if (读取开局模式() === '原著角色') {
        var 首个选项 = 选择框.querySelector('option[value]:not([value=""])');
        if (首个选项) 选择框.value = 首个选项.value;
    }
    当前原著角色选择 = 选择框.value || '';
}

function 应用原著角色到表单(角色名) {
    var 时间线节点 = (document.getElementById('timeline-select') || {}).value || '13岁';
    var 投影 = 构建原著角色开场投影(角色名, 时间线节点);
    if (!投影) return false;
    当前原著角色选择 = 投影.角色名;
    var 角色数据 = 投影.角色数据;
    var 属性 = 角色数据.属性 || {};
    var 武魂 = 读取原著角色武魂表单(角色数据);
    var 副职业 = 读取原著角色副职业表单(角色数据);
    设置表单值('char-name', 投影.角色名, true);
    设置表单值('char-gender', 属性.性别 || '男', true);
    设置表单值('char-age', 属性.年龄 !== undefined ? 属性.年龄 : 6, true);
    写入开场生日(属性.生日 || 读取开场生日());
    设置表单值('char-loc', 角色数据.状态 && 角色数据.状态.位置 ? 角色数据.状态.位置 : '', true);
    设置表单值('char-spirit', 武魂.名称 || '未觉醒', true);
    设置表单值('char-talent', 角色库天赋转表单选项(属性.天赋梯队), true);
    设置表单值('char-personality', 格式化开场表单文本(角色数据.性格), true);
    设置表单值('char-appearance', 格式化开场表单文本(角色数据.外貌 && (角色数据.外貌.长相描述 || 角色数据.外貌)), true);
