window.处理开场主按钮 = async function() {
    if (开场主按钮处理中) return;
    if (开场世界线已初始化) {
        window.发送开场白();
        return;
    }

    开场主按钮处理中 = true;
    设置开场主按钮忙碌(true, '[ 正在注入数据库剧情推进预设 ]');
    try {
        var 注入结果 = await window.注入数据库剧情推进预设();
        if (!注入结果 || !注入结果.success) {
            设置开场主按钮忙碌(false, '[ 初始化世界线 ]');
            return;
        }

        设置开场主按钮忙碌(true, '[ 正在写入MVU初始化 ]');
        showTemplateMessage('已注入并切换到' + (注入结果.presetName || '数据库剧情推进预设') + '，正在初始化世界线...');
        开场初始化结果 = await window.submitForm();
        if (!开场初始化结果 || !开场初始化结果.开场发送文本) {
            throw new Error('MVU初始化未返回开场白文本');
        }
        开场待发送文本 = 开场初始化结果.开场发送文本;
        开场世界线已初始化 = true;
        切换开场主按钮为同步();
        设置开场主按钮忙碌(false);
        showTemplateMessage('数据库剧情推进预设已注入，世界线初始化完成，可以发送开场白。');
        if (confirm('数据库剧情推进预设已注入并切换。是否现在设置 API？')) {
            打开数据库设置界面();
        }
    } catch (错误) {
        console.error('[开场白] 开场主按钮执行失败:', 错误);
        showTemplateMessage('世界线初始化失败：' + (错误 && 错误.message ? 错误.message : String(错误 || '未知错误')), true);
        设置开场主按钮忙碌(true, 'MVU加载失败，请重新开启新聊天');
    } finally {
        开场主按钮处理中 = false;
    }
};

window.updateLocByTimeline = function() {
