window.updateSpiritTypes = function() {
    var container = document.getElementById('spirit-types-container');
    if (!container) return;

    var oldTypes = [];
    var oldDescs = [];
    document.querySelectorAll('.spirit-type-select').forEach(function(s) { oldTypes.push(s.value); });
    document.querySelectorAll('.spirit-desc-input').forEach(function(i) { oldDescs.push(i.value); });

    var spiritInput = document.getElementById('char-spirit');
    var spirits = splitSpirits(spiritInput ? spiritInput.value : '');
    var options = ['强攻系', '敏攻系', '控制系', '防御系', '辅助系', '治疗系', '食物系', '精神系', '元素系'];
    var html = '';

    spirits.forEach(function(spiritName, index) {
        var oldType = oldTypes[index] || '强攻系';
        var oldDesc = oldDescs[index] || '';

        html += '<div class="spirit-type-item">';
        html += '<div style="font-size:14px; color:#2dd4bf; margin-bottom:12px; font-weight:600; border-bottom:1px solid rgba(45,212,191,0.2); padding-bottom:8px;">❖ ' + spiritName + '</div>';
        html += '<label style="font-size:12px; color:#94a3b8; margin-bottom:6px; display:block; font-weight:500;">系别</label>';
        html += '<select class="form-control spirit-type-select" style="margin-bottom:10px;">';
        options.forEach(function(opt) {
